import{_ as s,o as e,c as i,a as r}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"数据库层开发-高性能访问-数据分片-ShardingSphere生态","description":"","frontmatter":{},"headers":[],"relativePath":"data/performance/sharding/tools/shardingsphere.md","filePath":"data/performance/sharding/tools/shardingsphere.md"}'),n={name:"data/performance/sharding/tools/shardingsphere.md"};function t(l,a,h,d,o,p){return e(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="数据库层开发-高性能访问-数据分片-shardingsphere生态" tabindex="-1">数据库层开发-高性能访问-数据分片-ShardingSphere生态 <a class="header-anchor" href="#数据库层开发-高性能访问-数据分片-shardingsphere生态" aria-label="Permalink to &quot;数据库层开发-高性能访问-数据分片-ShardingSphere生态&quot;">​</a></h1><h2 id="一、shardingsphere概述" tabindex="-1">一、ShardingSphere概述 <a class="header-anchor" href="#一、shardingsphere概述" aria-label="Permalink to &quot;一、ShardingSphere概述&quot;">​</a></h2><h3 id="_1-1-什么是shardingsphere" tabindex="-1">1.1 什么是ShardingSphere <a class="header-anchor" href="#_1-1-什么是shardingsphere" aria-label="Permalink to &quot;1.1 什么是ShardingSphere&quot;">​</a></h3><p>Apache ShardingSphere是一套开源的分布式数据库中间件解决方案生态圈，由Sharding-JDBC、Sharding-Proxy和Sharding-Sidecar这3款相互独立的产品组成。它最早由当当网开源（Sharding-JDBC），目前由Apache基金会孵化并成为顶级项目。目前在GitHub上星标超过19.8k，社区非常活跃。</p><p>从本质上说，ShardingSphere是一个独立的数据库中间件平台，它基于Database Plus理念，旨在构建异构数据库上层的标准和生态，并补充数据库所缺失的能力。ShardingSphere关注的是如何充分合理地利用数据库的计算和存储能力，而非实现一个全新的数据库。</p><h3 id="_1-2-三大法宝-连接、增强、可插拔" tabindex="-1">1.2 三大法宝：连接、增强、可插拔 <a class="header-anchor" href="#_1-2-三大法宝-连接、增强、可插拔" aria-label="Permalink to &quot;1.2 三大法宝：连接、增强、可插拔&quot;">​</a></h3><p>ShardingSphere取得成功的三大核心特性是：</p><ul><li><strong>连接</strong>：兼容既有数据库，统一数据库入口（数据库网关），使用户可以透明地访问数据库及其外围生态圈</li><li><strong>增强</strong>：捕获数据库入口，提供分片、读写分离、影子库、数据加密与脱敏、安全性、审计与授权、熔断、QoS和可观测性等多种功能</li><li><strong>可插拔</strong>：允许功能组件以可插拔的方式进行扩展，开发者可以像使用积木一样定制系统</li></ul><h3 id="_1-3-三层可插拔架构" tabindex="-1">1.3 三层可插拔架构 <a class="header-anchor" href="#_1-3-三层可插拔架构" aria-label="Permalink to &quot;1.3 三层可插拔架构&quot;">​</a></h3><p>ShardingSphere 5.x版本开始致力于可插拔架构，分为三层：</p><ul><li><strong>L1内核层</strong>：数据库基本能力的抽象，包括查询优化器、分布式事务引擎、分布式执行引擎、权限引擎和调度引擎等。所有组件都必须存在，但具体实现可通过可插拔的方式更换</li><li><strong>L2功能层</strong>：提供增量能力，主要包括数据分片、读写分离、数据库高可用、数据加密、影子库等。所有组件均可选，组件之间完全隔离，可通过叠加的方式相互配合使用</li><li><strong>L3生态层</strong>：对接和融入现有数据库生态，包括数据库协议、SQL解析器和存储适配器</li></ul><h2 id="二、三大核心产品" tabindex="-1">二、三大核心产品 <a class="header-anchor" href="#二、三大核心产品" aria-label="Permalink to &quot;二、三大核心产品&quot;">​</a></h2><h3 id="_2-1-shardingsphere-jdbc" tabindex="-1">2.1 ShardingSphere-JDBC <a class="header-anchor" href="#_2-1-shardingsphere-jdbc" aria-label="Permalink to &quot;2.1 ShardingSphere-JDBC&quot;">​</a></h3><p>ShardingSphere-JDBC是ShardingSphere的第一个产品，定位为轻量级Java框架，在Java的JDBC层提供额外服务。</p><p><strong>核心特点</strong>：</p><ul><li>使用客户端直连数据库，以JAR包形式提供服务，无需额外部署和依赖</li><li>可理解为增强版的JDBC驱动，完全兼容JDBC和各种ORM框架</li><li>适用于任何基于JDBC的ORM框架，如JPA、Hibernate、MyBatis、Spring JDBC Template等</li><li>支持任何第三方的数据库连接池，如DBCP、C3P0、BoneCP、Druid、HikariCP等</li><li>支持任意实现JDBC规范的数据库，包括MySQL、Oracle、SQLServer、PostgreSQL等</li></ul><p><strong>适用场景</strong>：采用无中心化架构，适用于Java开发的高性能轻量级OLTP应用。</p><h3 id="_2-2-shardingsphere-proxy" tabindex="-1">2.2 ShardingSphere-Proxy <a class="header-anchor" href="#_2-2-shardingsphere-proxy" aria-label="Permalink to &quot;2.2 ShardingSphere-Proxy&quot;">​</a></h3><p>ShardingSphere-Proxy是独立的数据库代理端，对异构语言提供支持。</p><p><strong>核心特点</strong>：</p><ul><li>提供MySQL和PostgreSQL协议的支持</li><li>透明化数据库操作，对DBA更加友好</li><li>提供静态入口，支持异构语言</li></ul><p><strong>适用场景</strong>：OLAP应用以及对分片数据库进行管理和运维的场景。</p><h3 id="_2-3-shardingsphere-sidecar-规划中" tabindex="-1">2.3 ShardingSphere-Sidecar（规划中） <a class="header-anchor" href="#_2-3-shardingsphere-sidecar-规划中" aria-label="Permalink to &quot;2.3 ShardingSphere-Sidecar（规划中）&quot;">​</a></h3><p>ShardingSphere-Sidecar是ShardingSphere的第三个产品，目前仍然在规划中。</p><p><strong>核心特点</strong>：</p><ul><li>定位为Kubernetes或Mesos的云原生数据库代理</li><li>以DaemonSet或Sidecar的形式代理所有对数据库的访问</li><li>通过无中心、零侵入的方案提供与数据库交互的啮合层，即Database Mesh（数据库网格）</li></ul><p>JDBC和Proxy在功能上基本一致，主要区别在于部署形态。两者可以混合部署配合使用。</p><h3 id="_2-4-三种产品对比" tabindex="-1">2.4 三种产品对比 <a class="header-anchor" href="#_2-4-三种产品对比" aria-label="Permalink to &quot;2.4 三种产品对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>ShardingSphere-JDBC</th><th>ShardingSphere-Proxy</th><th>ShardingSphere-Sidecar</th></tr></thead><tbody><tr><td>数据库支持</td><td>任意（JDBC规范）</td><td>MySQL/PostgreSQL</td><td>MySQL/PostgreSQL</td></tr><tr><td>连接消耗数</td><td>高</td><td>低</td><td>高</td></tr><tr><td>异构语言</td><td>仅Java</td><td>任意</td><td>任意</td></tr><tr><td>性能</td><td>损耗低</td><td>损耗略高</td><td>损耗低</td></tr><tr><td>无中心化</td><td>是</td><td>否</td><td>是</td></tr><tr><td>静态入口</td><td>无</td><td>有</td><td>无</td></tr></tbody></table><h2 id="三、数据分片核心概念" tabindex="-1">三、数据分片核心概念 <a class="header-anchor" href="#三、数据分片核心概念" aria-label="Permalink to &quot;三、数据分片核心概念&quot;">​</a></h2><h3 id="_3-1-什么是数据分片" tabindex="-1">3.1 什么是数据分片 <a class="header-anchor" href="#_3-1-什么是数据分片" aria-label="Permalink to &quot;3.1 什么是数据分片&quot;">​</a></h3><p>数据分片是指按照某个业务维度，将存放在单一数据库中的数据分散地存放至多个数据库或表中，以达到提升性能的效果。当单表数据量过大时，B+树索引深度增加会导致磁盘访问的I/O次数增加，查询性能下降。</p><p>分库分表的本质是将单一数据库中的数据按照预设规则拆分到多个物理数据库（分库）和多个数据表（分表）中。</p><h3 id="_3-2-分片类型" tabindex="-1">3.2 分片类型 <a class="header-anchor" href="#_3-2-分片类型" aria-label="Permalink to &quot;3.2 分片类型&quot;">​</a></h3><p><strong>水平分片</strong>：同一个表按照某个分片键（如user_id、order_id）拆到多个物理表或库中。</p><p><strong>垂直分片</strong>：按业务模块拆分到不同库，例如用户、订单、支付表放到不同库。</p><p>ShardingSphere重点做水平分片。</p><h3 id="_3-3-核心术语" tabindex="-1">3.3 核心术语 <a class="header-anchor" href="#_3-3-核心术语" aria-label="Permalink to &quot;3.3 核心术语&quot;">​</a></h3><ul><li><strong>逻辑表</strong>：应用层使用的表名，如<code>t_order</code></li><li><strong>物理表</strong>：实际存在于数据库中的表名，如<code>t_order_0</code>、<code>t_order_1</code></li><li><strong>分片键（Sharding Key）</strong> ：用于将数据库（表）水平拆分的数据库字段</li><li><strong>分片算法（Sharding Algorithm）</strong> ：用于将数据分片的算法，支持<code>=</code>、<code>&gt;=</code>、<code>&lt;=</code>、<code>&gt;</code>、<code>&lt;</code>、<code>BETWEEN</code>和<code>IN</code>进行分片</li><li><strong>数据节点</strong>：数据分片的最小物理单元，由数据源名称和真实表组成</li></ul><h3 id="_3-4-分片键的选择" tabindex="-1">3.4 分片键的选择 <a class="header-anchor" href="#_3-4-分片键的选择" aria-label="Permalink to &quot;3.4 分片键的选择&quot;">​</a></h3><p>分片键是连接逻辑表与物理表的关键。选择分片键时应遵循以下原则：</p><ol><li><strong>高基数</strong>：分片键应有足够多的取值，避免数据倾斜</li><li><strong>高查询频率</strong>：分片键应为查询WHERE子句中的高频字段</li><li><strong>低更新频率</strong>：分片键值应尽量避免更新</li><li><strong>避免自增ID</strong>：自增ID作为分片键容易导致热点</li><li><strong>推荐使用UUID或Snowflake ID + 哈希取模</strong></li></ol><p>常见的最佳分片键包括用户ID、订单ID、设备ID等业务天然分片键。</p><h2 id="四、分片策略与算法" tabindex="-1">四、分片策略与算法 <a class="header-anchor" href="#四、分片策略与算法" aria-label="Permalink to &quot;四、分片策略与算法&quot;">​</a></h2><h3 id="_4-1-分片策略类型" tabindex="-1">4.1 分片策略类型 <a class="header-anchor" href="#_4-1-分片策略类型" aria-label="Permalink to &quot;4.1 分片策略类型&quot;">​</a></h3><p>ShardingSphere支持四种分片策略：</p><p><strong>1. 标准分片策略（Standard Sharding）</strong></p><ul><li>基于单分片键的精确路由</li><li>适用于大多数场景</li><li>分片算法支持<code>=</code>、<code>IN</code>、<code>BETWEEN AND</code>等操作</li></ul><p><strong>2. 复合分片策略（Complex Sharding）</strong></p><ul><li>多分片键组合分片，如<code>(user_id, region)</code></li><li>适合多维查询场景</li></ul><p><strong>3. Hint分片策略</strong></p><ul><li>通过编程强制指定路由</li><li>需要用户实现<code>HintShardingAlgorithm</code>接口</li><li>灵活性高但需手动管理</li></ul><p><strong>4. 行表达式分片</strong></p><ul><li>使用Groovy表达式简化配置</li><li>例如：<code>t_user_\${u_id % 8}</code>表示按<code>u_id</code>模8分成8张表</li></ul><h3 id="_4-2-内置分片算法" tabindex="-1">4.2 内置分片算法 <a class="header-anchor" href="#_4-2-内置分片算法" aria-label="Permalink to &quot;4.2 内置分片算法&quot;">​</a></h3><p>ShardingSphere内置了多种分片算法：</p><table tabindex="0"><thead><tr><th>算法类型</th><th>适用场景</th><th>示例</th></tr></thead><tbody><tr><td>INLINE</td><td>简单取模</td><td><code>t_order_\${order_id % 4}</code></td></tr><tr><td>HASH</td><td>均匀分布</td><td>使用MurmurHash算法</td></tr><tr><td>MOD</td><td>固定分片</td><td><code>db_\${user_id % 8}</code></td></tr><tr><td>DATE</td><td>时间分片</td><td><code>t_log_202401</code>, <code>t_log_202402</code></td></tr><tr><td>AUTO_INTERVAL</td><td>自动区间</td><td>按日期自动创建新表</td></tr></tbody></table><h3 id="_4-3-配置示例" tabindex="-1">4.3 配置示例 <a class="header-anchor" href="#_4-3-配置示例" aria-label="Permalink to &quot;4.3 配置示例&quot;">​</a></h3><p>以下是一个订单表的分库分表配置示例（2个库，每个库4张表）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_17hn0y">rules</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_140thh">  - </span><span class="__shiki_1itgoe">!SHARDING</span></span>
<span class="line"><span class="__shiki_17hn0y">    tables</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">      t_order</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">        actualDataNodes</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">ds_\${0..1}.t_order_\${0..3}</span></span>
<span class="line"><span class="__shiki_17hn0y">        databaseStrategy</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">          standard</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">            shardingColumn</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">order_id</span></span>
<span class="line"><span class="__shiki_17hn0y">            shardingAlgorithmName</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">database_inline</span></span>
<span class="line"><span class="__shiki_17hn0y">        tableStrategy</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">          standard</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">            shardingColumn</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">user_id</span></span>
<span class="line"><span class="__shiki_17hn0y">            shardingAlgorithmName</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">table_inline</span></span>
<span class="line"><span class="__shiki_17hn0y">    shardingAlgorithms</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">      database_inline</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">        type</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">INLINE</span></span>
<span class="line"><span class="__shiki_17hn0y">        props</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">          algorithm-expression</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">ds_\${order_id % 2}</span></span>
<span class="line"><span class="__shiki_17hn0y">      table_inline</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">        type</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">INLINE</span></span>
<span class="line"><span class="__shiki_17hn0y">        props</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">          algorithm-expression</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">t_order_\${user_id % 4}</span></span></code></pre></div><ul><li><code>actualDataNodes</code>定义了物理节点：<code>ds0</code>和<code>ds1</code>两个库，每个库<code>t_order_0</code>到<code>t_order_3</code>四张表</li><li>分库算法：<code>order_id</code>取模2</li><li>分表算法：<code>user_id</code>取模4</li></ul><h2 id="五、数据分片内核流程" tabindex="-1">五、数据分片内核流程 <a class="header-anchor" href="#五、数据分片内核流程" aria-label="Permalink to &quot;五、数据分片内核流程&quot;">​</a></h2><p>ShardingSphere的三个产品的数据分片主要流程是完全一致的。核心流程由以下六个步骤组成：</p><h3 id="_5-1-sql解析" tabindex="-1">5.1 SQL解析 <a class="header-anchor" href="#_5-1-sql解析" aria-label="Permalink to &quot;5.1 SQL解析&quot;">​</a></h3><p>分为词法解析和语法解析：</p><ul><li><strong>词法解析</strong>：将SQL拆分为一个个不可再分的单词</li><li><strong>语法解析</strong>：对SQL进行理解，提炼出解析上下文</li></ul><p>解析上下文包括表、选择项、排序项、分组项、聚合函数、分页信息、查询条件以及可能需要修改的占位符标记。</p><h3 id="_5-2-执行器优化" tabindex="-1">5.2 执行器优化 <a class="header-anchor" href="#_5-2-执行器优化" aria-label="Permalink to &quot;5.2 执行器优化&quot;">​</a></h3><p>合并和优化分片条件，如处理OR等复杂条件。</p><h3 id="_5-3-sql路由" tabindex="-1">5.3 SQL路由 <a class="header-anchor" href="#_5-3-sql路由" aria-label="Permalink to &quot;5.3 SQL路由&quot;">​</a></h3><p>根据解析上下文匹配用户配置的分片策略，生成路由路径。目前支持：</p><ul><li><strong>分片路由</strong>：根据分片规则将查询路由到特定分片</li><li><strong>广播路由</strong>：将查询发送到所有分片</li></ul><p><strong>重要</strong>：SQL中如果无分片字段，将执行全路由（广播路由），性能较差。</p><h3 id="_5-4-sql改写" tabindex="-1">5.4 SQL改写 <a class="header-anchor" href="#_5-4-sql改写" aria-label="Permalink to &quot;5.4 SQL改写&quot;">​</a></h3><p>将SQL改写为在真实数据库中可正确执行的语句。例如：</p><ul><li>原始SQL：<code>SELECT * FROM t_order WHERE order_id = 123;</code></li><li>改写后：<code>SELECT * FROM ds_1.t_order_3 WHERE order_id = 123;</code></li></ul><p>SQL改写分为正确性改写和优化改写。</p><h3 id="_5-5-sql执行" tabindex="-1">5.5 SQL执行 <a class="header-anchor" href="#_5-5-sql执行" aria-label="Permalink to &quot;5.5 SQL执行&quot;">​</a></h3><p>通过多线程执行器异步执行。将改写后的真实SQL发送到底层数据库执行。</p><h3 id="_5-6-结果归并" tabindex="-1">5.6 结果归并 <a class="header-anchor" href="#_5-6-结果归并" aria-label="Permalink to &quot;5.6 结果归并&quot;">​</a></h3><p>将多个执行结果集归并，以便通过统一的JDBC接口输出。结果归并包括：</p><ul><li><strong>流式归并</strong>：边读取边归并</li><li><strong>内存归并</strong>：全部加载到内存后归并</li><li><strong>追加归并</strong>：使用装饰者模式</li></ul><p>整个分片流程对业务代码完全透明，开发者无需修改SQL逻辑即可享受分片带来的性能提升。</p><h2 id="六、扩展功能" tabindex="-1">六、扩展功能 <a class="header-anchor" href="#六、扩展功能" aria-label="Permalink to &quot;六、扩展功能&quot;">​</a></h2><h3 id="_6-1-读写分离" tabindex="-1">6.1 读写分离 <a class="header-anchor" href="#_6-1-读写分离" aria-label="Permalink to &quot;6.1 读写分离&quot;">​</a></h3><p>读写分离是应对高压力业务访问的手段之一。ShardingSphere基于对SQL语义理解及底层数据库拓扑感知能力，提供灵活的读写流量拆分和读流量负载均衡。</p><p><strong>核心机制</strong>：</p><ul><li><strong>SQL路由</strong>：根据SQL类型（SELECT/WRITE）自动路由到主库或从库</li><li><strong>负载均衡</strong>：支持轮询、随机权重等算法分配读请求到多个从库</li></ul><p>传统做法是应用端自己判断走主库或从库，代码复杂且容易出错。ShardingSphere自动管理路由和连接，减少应用端逻辑。</p><h3 id="_6-2-数据加密与脱敏" tabindex="-1">6.2 数据加密与脱敏 <a class="header-anchor" href="#_6-2-数据加密与脱敏" aria-label="Permalink to &quot;6.2 数据加密与脱敏&quot;">​</a></h3><p>ShardingSphere提供完整、透明、安全、低成本的数据加密及脱敏解决方案。支持字段级加密与脱敏。</p><p><strong>内置加密算法</strong>：</p><ul><li>AES</li><li>MD5</li><li>RC4</li><li>SM3</li><li>SM4</li></ul><p>用户也可以通过实现ShardingSphere提供的接口自行实现加解密算法。</p><h3 id="_6-3-分布式事务" tabindex="-1">6.3 分布式事务 <a class="header-anchor" href="#_6-3-分布式事务" aria-label="Permalink to &quot;6.3 分布式事务&quot;">​</a></h3><p>ShardingSphere提供了三种模式的分布式事务：</p><p><strong>1. LOCAL（本地事务）</strong></p><ul><li>默认模式，适用于单分片事务</li></ul><p><strong>2. XA（两阶段事务）</strong></p><ul><li>基于XA协议的强一致性分布式事务</li><li>默认的XA事务管理器为Atomikos</li><li>适合对一致性要求高的场景</li></ul><p><strong>3. BASE（柔性事务）</strong></p><ul><li>基于BASE理论的最终一致性事务</li><li>Seata AT事务作为BASE柔性事务的一种实现，可以无缝接入ShardingSphere生态</li><li>Seata的AT模式通过全局锁和回滚日志实现无侵入式的分布式事务，性能优于XA</li></ul><h3 id="_6-4-分布式主键" tabindex="-1">6.4 分布式主键 <a class="header-anchor" href="#_6-4-分布式主键" aria-label="Permalink to &quot;6.4 分布式主键&quot;">​</a></h3><p>ShardingSphere不仅提供了内置的分布式主键生成器（如UUID、SNOWFLAKE），还抽离出分布式主键生成器的接口，方便用户实现自定义的自增主键生成器。</p><h3 id="_6-5-弹性伸缩-数据迁移" tabindex="-1">6.5 弹性伸缩（数据迁移） <a class="header-anchor" href="#_6-5-弹性伸缩-数据迁移" aria-label="Permalink to &quot;6.5 弹性伸缩（数据迁移）&quot;">​</a></h3><p>ShardingSphere提供统一的伸缩工具和规则，让迁移自动化、可观测、不中断。</p><p>弹性伸缩模块将一次伸缩拆解为4个主要阶段：</p><ol><li><strong>准备阶段</strong>：校验数据源连通性及权限，统计存量数据，记录日志位点，根据数据量和并行度对任务进行分片</li><li><strong>存量数据迁移阶段</strong>：使用<code>SELECT *</code>获取存量数据，使用<code>INSERT</code>迁移到目标库</li><li><strong>增量数据同步阶段</strong>：使用binlog实时同步迁移过程中的新增/更新/删除操作</li><li><strong>切换路由配置</strong>：全量+增量同步完成后，更新分片规则，应用自动路由到新分库/分表</li></ol><p>整个过程对应用透明，应用只使用逻辑库表名，不关心底层库表变化。ShardingSphere采用&quot;双集群切换&quot;的方式实现平滑迁移。</p><h3 id="_6-6-影子库压测" tabindex="-1">6.6 影子库压测 <a class="header-anchor" href="#_6-6-影子库压测" aria-label="Permalink to &quot;6.6 影子库压测&quot;">​</a></h3><p>在生产环境做压测时，业务代码走真实链路，但数据不能污染生产库。ShardingSphere通过影子库路由实现：</p><ul><li>压测流量 → SQL自动路由到影子库</li><li>正常流量 → 继续走生产库</li></ul><p>关键是要识别哪些SQL是压测流量，因此需要配置影子算法。</p><h2 id="七、最佳实践总结" tabindex="-1">七、最佳实践总结 <a class="header-anchor" href="#七、最佳实践总结" aria-label="Permalink to &quot;七、最佳实践总结&quot;">​</a></h2><h3 id="_7-1-分片键选择" tabindex="-1">7.1 分片键选择 <a class="header-anchor" href="#_7-1-分片键选择" aria-label="Permalink to &quot;7.1 分片键选择&quot;">​</a></h3><ol><li>优先选择业务天然分片键（如用户ID、订单ID），避免使用自增ID</li><li>分片键必须为查询高频字段</li><li>遵循&quot;高基数、高查询频率、低更新频率&quot;原则</li><li>SQL中如果无分片字段，将执行全路由，性能较差</li></ol><h3 id="_7-2-事务边界控制" tabindex="-1">7.2 事务边界控制 <a class="header-anchor" href="#_7-2-事务边界控制" aria-label="Permalink to &quot;7.2 事务边界控制&quot;">​</a></h3><p>单个事务操作的分片数建议不超过3个。</p><h3 id="_7-3-分页查询优化" tabindex="-1">7.3 分页查询优化 <a class="header-anchor" href="#_7-3-分页查询优化" aria-label="Permalink to &quot;7.3 分页查询优化&quot;">​</a></h3><p>避免使用<code>LIMIT 1000000, 10</code>这种深分页。尽量带上分片键查询，或使用标签表、冗余字段来避免跨库排序。</p><h3 id="_7-4-配置与测试" tabindex="-1">7.4 配置与测试 <a class="header-anchor" href="#_7-4-配置与测试" aria-label="Permalink to &quot;7.4 配置与测试&quot;">​</a></h3><ol><li>使用ShardingSphere-Proxy的<code>PREVIEW SQL</code>验证路由</li><li>先在测试环境验证分片策略，再逐步放量</li></ol><h3 id="_7-5-版本选择" tabindex="-1">7.5 版本选择 <a class="header-anchor" href="#_7-5-版本选择" aria-label="Permalink to &quot;7.5 版本选择&quot;">​</a></h3><p>新项目推荐使用ShardingSphere 5.5.0及以上版本，支持动态读写分离优化、CDC数据同步增强等最新功能，修复了历史版本中分片路由与事务管理的兼容性问题。</p><h3 id="_7-6-产品选型建议" tabindex="-1">7.6 产品选型建议 <a class="header-anchor" href="#_7-6-产品选型建议" aria-label="Permalink to &quot;7.6 产品选型建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐产品</th></tr></thead><tbody><tr><td>Java应用、高性能OLTP</td><td>ShardingSphere-JDBC</td></tr><tr><td>异构语言、DBA运维管理</td><td>ShardingSphere-Proxy</td></tr><tr><td>云原生、Kubernetes环境</td><td>ShardingSphere-Sidecar（规划中）</td></tr><tr><td>混合场景</td><td>JDBC + Proxy 混合部署</td></tr></tbody></table><p>ShardingSphere在兼容性、灵活性、社区支持等方面具备显著优势，适合中大型项目的长期维护。</p>`,127)])])}const g=s(n,[["render",t]]);export{c as __pageData,g as default};
